import {materialRows} from './room-shopping.mjs';
import {wallSegments,floorArea,perimeter} from './room-geometry.mjs';
const money=n=>n.toLocaleString('ru-RU',{maximumFractionDigits:2});
export function validateBudget(b){if(b===undefined)return;if(!b||typeof b!=='object'||Array.isArray(b)||!b.prices||typeof b.prices!=='object'||Array.isArray(b.prices)||Object.keys(b.prices).length>200)throw Error('Некорректный бюджет');for(const [id,price] of Object.entries(b.prices))if(id.length>2000||typeof price!=='number'||!Number.isFinite(price)||price<0||price>1e9)throw Error('Цена должна быть числом от 0 до 1 000 000 000 ₸');}
export function budgetRows(p){const rows=materialRows(p).map(r=>({id:'material:'+JSON.stringify([r.where,r.name,r.unit]),category:'Материалы',name:r.where+' — '+r.name,quantity:r.quantity,unit:r.unit,detail:r.amount}));
 rows.push({id:'material:other',category:'Материалы',name:'Клей, подложка, расходники и доставка',quantity:1,unit:'позиция целиком',detail:'Внесите общую сумму после подбора'});
 const segments=wallSegments(p),areas={paint:0,wallpaper:0,plaster:0};p.walls.forEach((s,i)=>areas[s.finish]+=Math.max(0,segments[i].length*p.height-p.openings.filter(o=>o.wall===i).reduce((a,o)=>a+o.width*o.height,0)));
 const names={paint:'Покраска стен',wallpaper:'Поклейка обоев',plaster:'Нанесение декоративной штукатурки'};for(const [finish,area] of Object.entries(areas))if(area>0)rows.push({id:'work:wall:'+finish,category:'Работы',name:names[finish],quantity:area,unit:'м²',detail:'Чистая площадь; ставка за весь согласованный цикл'});
 rows.push({id:'work:floor:'+p.floor.finish,category:'Работы',name:p.floor.finish==='tile'?'Укладка плитки':'Укладка ламината',quantity:floorArea(p),unit:'м²',detail:'Площадь пола без запаса'});
 rows.push({id:'work:ceiling:'+p.ceiling.finish,category:'Работы',name:p.ceiling.finish==='stretch'?'Монтаж натяжного потолка':'Покраска потолка',quantity:floorArea(p),unit:'м²',detail:'Только работа; материал указан отдельно'});
 rows.push({id:'work:baseboard',category:'Работы',name:'Монтаж плинтуса',quantity:Math.max(0,perimeter(p)-p.openings.filter(o=>o.type==='door').reduce((a,o)=>a+o.width,0)),unit:'пог. м',detail:'Периметр без дверей и без запаса'});
 rows.push({id:'work:other',category:'Работы',name:'Подготовка, демонтаж, инженерия и прочие работы',quantity:1,unit:'позиция целиком',detail:'Общая сумма по предложению мастера'});
 return rows.map(r=>{const price=Object.hasOwn(p.budget?.prices||{},r.id)?p.budget.prices[r.id]:null;return {...r,price,total:price===null?null:Math.round(price*r.quantity*100)/100};});}
export function budgetSummary(p){const rows=budgetRows(p),materials=rows.filter(r=>r.category==='Материалы').reduce((a,r)=>a+(r.total??0),0),work=rows.filter(r=>r.category==='Работы').reduce((a,r)=>a+(r.total??0),0);return {rows,materials,work,total:Math.round((materials+work)*100)/100,missing:rows.filter(r=>r.price===null).length};}
export function budgetText(p){const b=budgetSummary(p);return `ПРЕДВАРИТЕЛЬНЫЙ БЮДЖЕТ ПО ВАШИМ ЦЕНАМ (₸)\n${b.rows.map(r=>`${r.category} — ${r.name}: ${money(r.quantity)} ${r.unit} × ${r.price===null?'цена не указана':money(r.price)+' ₸'}${r.total===null?'':' = '+money(r.total)+' ₸'}`).join('\n')}\nМатериалы: ${money(b.materials)} ₸; работы: ${money(b.work)} ₸.\n${b.missing?'Учтённая сумма':'Итого по введённым ценам'}: ${money(b.total)} ₸. Не оценено позиций: ${b.missing}.\nЦены введены пользователем, это не предложение TED. Проверить состав работ и исключить двойной учёт материалов в комплексных расценках.`;}
